export interface Pattern {
	id: string;
	name: string;
	order: number;
	multiSelect: boolean;
	/**
	 * Array of canvas IDs this pattern is relevant on. Missing / empty =
	 * applies everywhere (back-compat default for older files). The Checklist
	 * SA app's `data/lookups/patterns.json` is generated by
	 * `scripts/sync-patterns.sh` filtered to patterns whose `appliesTo`
	 * includes `canvas_checklist`, so under normal operation everything in
	 * this file IS canvas_checklist-applicable.
	 */
	appliesTo?: string[];
	/**
	 * Per-user toggle controlling whether this pattern shows on the canvas.
	 * Missing = `true` (back-compat). The Manage Pattern Types UI lists
	 * every pattern with a toggle switch — turning a pattern off hides it
	 * from the canvas but keeps its values + descriptions in the catalog
	 * so the action is reversible. Stored in the `*-patterns-overrides`
	 * localStorage key; the canvas filters via `sortedPatterns.filter(p
	 * => p.enabled !== false)`.
	 */
	enabled?: boolean;
}

export interface PatternsFile {
	version: string;
	patterns: Pattern[];
}

export type Lookups = Record<string, string[]>;

export interface Dictionary {
	patterns: Record<string, string>;
	values: Record<string, Record<string, string>>;
}

export interface Policy {
	id: string;
	name: string;
	description: string;
	category: string;
	rule: string;
}

export interface PoliciesFile {
	version: string;
	categories: string[];
	policies: Policy[];
}

export interface Layer {
	id: string;
	name: string;
	order: number;
	values: Record<string, string[]>;
	notes: Record<string, string>;
	policies: Record<string, string[]>;
}

export interface Checklist {
	version: string;
	id: string;
	name: string;
	description: string;
	layers: Layer[];
	patternOrder?: string[];
}
